CREATE FUNCTION calculate_rcp(vehicle_reg VARCHAR)
RETURNS VARCHAR AS
$$
DECLARE
    dist_done NUMERIC;
    dist_left NUMERIC;
BEGIN
    SELECT distdonekm, distleftkm
    INTO dist_done, dist_left
    FROM transportinfo
    WHERE vehiclereg = vehicle_reg;

    IF dist_done IS NULL AND dist_left IS NULL THEN
        RETURN 'Unknown';
    ELSIF dist_left = 0 THEN
        RETURN 'Completed';
    ELSE
        RETURN 'In Progress';
    END IF;
END;
$$ LANGUAGE plpgsql;

